import {repoTreeSVG,repoTreeText,REPO_NODES} from './repo-tree.js';
export const REPO_GUIDE=await fetch('repo-guide.json').then(r=>r.json());
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readmePreview(){return `<div class="readme-preview"><h4>Rätselhaft! – TEI-Korpus</h4><p>Für Korpusanalysen verwenden Sie <code>data/tei</code> dieses Releases. Eine XML-Datei entspricht einem Buch oder einer Sammlung.</p><h5>Erste Untersuchung</h5><p>Kleines Beispiel: <code>examples/nutzungsstart/</code></p><pre><code>python examples/nutzungsstart/untersuchen.py</code></pre><p>Erwartet: drei Rätsel und drei zugeordnete Lösungen.</p><h5>Weiterarbeiten</h5><p>Auszeichnung und Dateinamen: <code>docs/</code><br>Zitation: <code>CITATION.cff</code><br>Nutzungsrechte: <code>LICENSE</code></p><p>Fehler mit Release und Rätselkennung als Issue melden. Nach Projektende: wichtige Korrekturen, neue Aufnahmen nach Kapazität.</p></div>`;}
export function repoDetailHTML(e){return `<p class="eyebrow">AUSGEWÄHLTER EINTRAG</p><h3 id="repo-detail-title">${escape(e.name)}</h3><p class="repo-purpose">${escape(e.purpose)}</p><details class="repo-preview" open><summary>Beispielausschnitt: ${escape(e.name)}</summary>${e.key==='readme'?readmePreview():`<pre><code>${escape(e.preview)}</code></pre>`}</details>${e.key==='readme'?`<details><summary>Dieselbe README als Markdown</summary><pre><code>${escape(e.preview)}</code></pre></details>`:''}<h4>So füllen und pflegen wir diesen Eintrag</h4><dl class="repo-lifecycle"><dt>Für wen? Welcher Ton?</dt><dd>${escape(e.audience)}</dd><dt>Wann planen?</dt><dd>${escape(e.plan)}</dd><dt>Wann anlegen?</dt><dd>${escape(e.create)}</dd><dt>Mindestens enthalten</dt><dd><ul>${e.minimum.map(t=>`<li>${escape(t)}</li>`).join('')}</ul></dd><dt>Wann und wie aktualisieren?</dt><dd>${escape(e.update)}</dd><dt>Prozess und Automatisierung</dt><dd>${escape(e.automation)}</dd></dl>`;}
export function repoExplorerHTML(print=false){return print?`<div class="repo-print-tree"><h3>Unser Publikationsrepo</h3><figure class="repo-tree">${repoTreeSVG()}</figure></div><h3>Planung und Pflege auf einen Blick</h3><p>Das vollständige Handbuch mit Zielgruppen, Mindestinhalt und Beispielausschnitten steht als repo-handbuch.md bereit.</p><div class="table-scroll"><table class="repo-maintenance-table"><thead><tr><th>Eintrag</th><th>Anlegen und planen</th><th>Pflegen</th></tr></thead><tbody>${REPO_GUIDE.filter(e=>!['tei','book'].includes(e.key)).map(e=>`<tr><th>${escape(e.name)}</th><td>${escape(e.plan)} ${escape(e.create)}</td><td>${escape(e.update)}</td></tr>`).join('')}</tbody></table></div>`:`<section class="repo-browser" aria-labelledby="repo-browser-title"><p class="eyebrow">DAS MUSTERREPO ERKUNDEN</p><h3 id="repo-browser-title">Ordner öffnen. Dateien ansehen. Pflege verstehen.</h3><p>Wählen Sie eine Datei oder einen Ordner im SVG. Ordner zeigen beim Öffnen einen Inhaltsausschnitt. Daneben stehen Beispiel, Zweck, Mindestinhalt, Zielgruppe und Pflegeablauf.</p><div class="repo-browser-layout"><div class="repo-browser-tree"><figure class="repo-tree">${repoTreeSVG({interactive:true})}<figcaption>Mit Klick, Enter oder Leertaste auswählen; Ordner erneut auswählen, um sie zu schließen.</figcaption></figure><div class="actions"><button type="button" data-repo-reset>Grundstruktur zeigen</button><a href="#repo-detail">Zum ausgewählten Eintrag ↓</a></div><details class="repo-tree-text"><summary>Ordnerstruktur als Text</summary>${repoTreeText()}</details><p><a href="assets/ordnerstruktur.svg" download>Ordnerbaum als SVG ↓</a></p></div><div><p id="repo-selection-status" class="small" role="status">README.md ausgewählt.</p><section id="repo-detail" class="repo-detail" aria-labelledby="repo-detail-title">${repoDetailHTML(REPO_GUIDE[0])}</section></div></div><p><a href="repo-handbuch.md" download>Alle Einträge mit Planung und Pflege als Markdown ↓</a></p></section>`;}
export function initRepoExplorer(){
 const root=document.querySelector('.repo-browser');if(!root)return;
 let selected='readme';const expanded=new Set(['data','tei']);
 const render=()=>{root.querySelector('.repo-tree').innerHTML=repoTreeSVG({interactive:true,selected,expanded:[...expanded]})+'<figcaption>Mit Klick, Enter oder Leertaste auswählen; Ordner erneut auswählen, um sie zu schließen.</figcaption>';const entry=REPO_GUIDE.find(e=>e.key===selected);root.querySelector('#repo-detail').innerHTML=repoDetailHTML(entry);root.querySelector('#repo-selection-status').textContent=entry.name+' ausgewählt. Beispiel und Pflegehinweise aktualisiert.';};
 root.addEventListener('click',e=>{const button=e.target.closest('[data-repo-select]');if(button){selected=button.dataset.repoSelect;const node=REPO_NODES.find(n=>n.key===selected);if(!node.file){if(expanded.has(selected))expanded.delete(selected);else expanded.add(selected);}render();root.querySelector(`[data-repo-select="${selected}"]`)?.focus({preventScroll:true});}if(e.target.closest('[data-repo-reset]')){selected='readme';expanded.clear();expanded.add('data');expanded.add('tei');render();}});
 root.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.closest('[data-repo-select]')){e.preventDefault();e.target.closest('[data-repo-select]').dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
}
